// El flujo corre el día 1. El mes que acaba de cerrar es el anterior.

const hoy = new Date();
hoy.setHours(0, 0, 0, 0);

// Primer y último día del mes pasado.
const desde = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);
const hasta = new Date(hoy.getFullYear(), hoy.getMonth(), 0);

const p = (n) => String(n).padStart(2, '0');
const aTexto = (f) => f.getFullYear() + '-' + p(f.getMonth() + 1) + '-' + p(f.getDate());

const MESES = [
  'enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio',
  'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre',
];

return [
  {
    json: {
      desde: aTexto(desde),
      hasta: aTexto(hasta),
      mes: desde.getFullYear() + '-' + p(desde.getMonth() + 1),
      mesTexto: MESES[desde.getMonth()] + ' de ' + desde.getFullYear(),
      hoy: aTexto(hoy),
    },
  },
];

// Alegra devuelve máximo 30 por llamada, así que el nodo anterior hace varias
// llamadas y entrega una página por cada una. Aquí las abrimos para quedar con
// un documento por item, y le ponemos una marca para saber de dónde salió.

const documentos = [];

for (const item of items) {
  const cuerpo = item.json;
  if (Array.isArray(cuerpo)) {
    documentos.push(...cuerpo);
  } else if (Array.isArray(cuerpo.data)) {
    documentos.push(...cuerpo.data);
  } else {
    documentos.push(cuerpo);
  }
}

return documentos.map((doc) => ({ json: { ...doc, _origen: 'venta-abierta' } }));

