return documentos.map((doc) => ({ json: { ...doc, _origen: 'borrador' } }));

// Alegra devuelve máximo 30 por llamada, así que el nodo anterior hace varias
// llamadas y entrega una página por cada una. Aquí las abrimos para quedar con
// un documento por item, y le ponemos una marca para saber de dónde salió.

const documentos = [];

for (const item of items) {
  const cuerpo = item.json;
  if (Array.isArray(cuerpo)) {
    documentos.push(...cuerpo);
  } else if (Array.isArray(cuerpo.data)) {
    documentos.push(...cuerpo.data);
  } else {
    documentos.push(cuerpo);
  }
}

return documentos.map((doc) => ({ json: { ...doc, _origen: 'compra-abierta' } }));

// ─── Puedes cambiar esto ──────────────────────────────────────────────
const MONEDA = 'COP';
const INCLUIR_MESES_ANTERIORES = true; // también lo que quedó colgado de antes
// ──────────────────────────────────────────────────────────────────────

const periodo = $('Calcular el mes que cerró').first().json;

const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

const fecha = (d) => {
  if (!d) return null;
  const f = new Date(String(d).slice(0, 10) + 'T00:00:00');
  return isNaN(f.getTime()) ? null : f;
};

const nombreDe = (p) => {
  const n = p && p.name;
  if (Array.isArray(n)) return n.filter(Boolean).join(' ');
  if (n && typeof n === 'object') return [n.firstName, n.lastName].filter(Boolean).join(' ');
  return n || 'Sin nombre';
};

const numeroDe = (x) =>
  String(
    (x.numberTemplate && x.numberTemplate.fullNumber) ||
      x.billNumber ||
      x.number ||
      x.id
  );

const saldoDe = (x) => Number(x.balance ?? Number(x.total ?? 0) - Number(x.totalPaid ?? 0));

const desde = fecha(periodo.desde);
const hasta = fecha(periodo.hasta);
const hoy = fecha(periodo.hoy);

const delMes = (x) => {
  const f = fecha(x.date);
  return f && f >= desde && f <= hasta;
};
const anterior = (x) => {
  const f = fecha(x.date);
  return f && f < desde;
};

const todos = items.map((i) => i.json);
const ventasAbiertas = todos.filter((x) => x._origen === 'venta-abierta');
const borradores = todos.filter((x) => x._origen === 'borrador');
const comprasAbiertas = todos.filter((x) => x._origen === 'compra-abierta');

const filas = [];

const agregar = (tipo, doc, contacto, queHacer) => {
  const vence = fecha(doc.dueDate);
  const saldo = saldoDe(doc);
  filas.push({
    clave: periodo.mes + '-' + tipo + '-' + doc.id,
    mes: periodo.mes,
    tipo,
    documento: numeroDe(doc),
    contacto,
    fecha: doc.date ? String(doc.date).slice(0, 10) : '',
    vence: doc.dueDate ? String(doc.dueDate).slice(0, 10) : '',
    dias: vence && hoy ? Math.round((hoy - vence) / 86400000) : 0,
    monto: Math.round(saldo || Number(doc.total ?? 0)),
    montoTexto: plata(saldo || Number(doc.total ?? 0)),
    queHacer,
    revisado: 'No',
  });
};

// 1. Facturas de venta del mes que cerró y que nadie ha pagado.
for (const f of ventasAbiertas) {
  if (!delMes(f)) continue;
  if (!(saldoDe(f) > 0)) continue;
  agregar('Venta sin cobrar', f, nombreDe(f.client), 'Cóbrala o provisiónala antes de cerrar');
}

// 2. Lo que quedó colgado de meses anteriores.
if (INCLUIR_MESES_ANTERIORES) {
  for (const f of ventasAbiertas) {
    if (!anterior(f)) continue;
    if (!(saldoDe(f) > 0)) continue;
    agregar('Venta vieja sin cobrar', f, nombreDe(f.client), 'Ya lleva más de un mes: decide si la cobras o la castigas');
  }
}

// 3. Facturas de venta que quedaron en borrador. Sin emitir, no existen.
for (const f of borradores) {
  if (!delMes(f)) continue;
  agregar('Borrador sin emitir', f, nombreDe(f.client), 'Emítela o bórrala: en borrador no cuenta para el mes');
}

// 4. Facturas de proveedor del mes que todavía debes.
for (const f of comprasAbiertas) {
  if (!delMes(f)) continue;
  if (!(saldoDe(f) > 0)) continue;
  agregar('Compra sin pagar', f, nombreDe(f.provider || f.client), 'Págala o déjala causada con su fecha real');
}

// 5. Clientes que facturaste en el mes sin identificación registrada.
const sinIdentificacion = new Map();
for (const f of [...ventasAbiertas, ...borradores]) {
  if (!delMes(f)) continue;
  const c = f.client || {};
  const id = c.identification || (c.identificationObject && c.identificationObject.number);
  if (id) continue;
  if (!c.id) continue;
  if (sinIdentificacion.has(String(c.id))) continue;
  sinIdentificacion.set(String(c.id), true);
  filas.push({
    clave: periodo.mes + '-Cliente sin identificación-' + c.id,
    mes: periodo.mes,
    tipo: 'Cliente sin identificación',
    documento: numeroDe(f),
    contacto: nombreDe(c),
    fecha: f.date ? String(f.date).slice(0, 10) : '',
    vence: '',
    dias: 0,
    monto: 0,
    montoTexto: plata(0),
    queHacer: 'Complétale la identificación en Alegra antes de reportar',
    revisado: 'No',
  });
}

// Si no hay nada pendiente igual mandamos una fila, para que el correo del
// día 1 siempre llegue y sepas que el flujo corrió.
if (!filas.length) {
  filas.push({
    clave: periodo.mes + '-Todo al día',
    mes: periodo.mes,
    tipo: 'Todo al día',
    documento: '',
    contacto: '',
    fecha: periodo.hasta,
    vence: '',
    dias: 0,
    monto: 0,
    montoTexto: plata(0),
    queHacer: 'No quedó nada pendiente de ' + periodo.mesTexto,
    revisado: 'Sí',
  });
}

// Lo de más plata primero, dentro de cada tipo.
const orden = [
  'Borrador sin emitir',
  'Cliente sin identificación',
  'Venta sin cobrar',
  'Compra sin pagar',
  'Venta vieja sin cobrar',
  'Todo al día',
];
filas.sort(
  (a, b) => orden.indexOf(a.tipo) - orden.indexOf(b.tipo) || b.monto - a.monto
);

return filas.map((fila) => ({ json: { ...fila, mesTexto: periodo.mesTexto } }));

// ─── Puedes cambiar esto ──────────────────────────────────────────────
const MONEDA = 'COP';
const MAXIMO_POR_BLOQUE = 10; // cuántas filas mostrar de cada tipo en el correo
// ──────────────────────────────────────────────────────────────────────

const filas = items.map((i) => i.json);
const mesTexto = (filas[0] && filas[0].mesTexto) || 'el mes pasado';

const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

const escapar = (t) =>
  String(t ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const todoAlDia = filas.length === 1 && filas[0].tipo === 'Todo al día';

// Agrupamos por tipo, respetando el orden en que vienen.
const tipos = [];
const porTipo = new Map();
for (const f of filas) {
  if (!porTipo.has(f.tipo)) {
    porTipo.set(f.tipo, []);
    tipos.push(f.tipo);
  }
  porTipo.get(f.tipo).push(f);
}

const bloque = (tipo) => {
  const lista = porTipo.get(tipo);
  const total = lista.reduce((s, f) => s + f.monto, 0);
  const cuerpo = lista
    .slice(0, MAXIMO_POR_BLOQUE)
    .map(
      (f) =>
        '<tr>' +
        '<td style="padding:8px 12px;border-bottom:1px solid #eee;">' + escapar(f.documento) + '</td>' +
        '<td style="padding:8px 12px;border-bottom:1px solid #eee;">' + escapar(f.contacto) + '</td>' +
        '<td style="padding:8px 12px;border-bottom:1px solid #eee;">' + escapar(f.fecha) + '</td>' +
        '<td style="padding:8px 12px;border-bottom:1px solid #eee;text-align:right;">' + escapar(f.montoTexto) + '</td>' +
        '</tr>'
    )
    .join('');

  return (
    '<h3 style="color:#30bbb7;margin:24px 0 4px;">' + escapar(tipo) +
    ' <span style="font-weight:normal;color:#666;">(' + lista.length +
    (total > 0 ? ' · ' + plata(total) : '') + ')</span></h3>' +
    '<p style="margin:0 0 8px;color:#666;font-size:13px;">' + escapar(lista[0].queHacer) + '</p>' +
    '<table style="border-collapse:collapse;width:100%;font-size:14px;">' +
    '<tr style="text-align:left;background:#f6f6f6;">' +
    '<th style="padding:8px 12px;">Documento</th>' +
    '<th style="padding:8px 12px;">Contacto</th>' +
    '<th style="padding:8px 12px;">Fecha</th>' +
    '<th style="padding:8px 12px;text-align:right;">Monto</th>' +
    '</tr>' + cuerpo + '</table>' +
    (lista.length > MAXIMO_POR_BLOQUE
      ? '<p style="margin:6px 0 0;color:#888;font-size:12px;">… y ' +
        (lista.length - MAXIMO_POR_BLOQUE) + ' más en la hoja.</p>'
      : '')
  );
};

const asunto = todoAlDia
  ? 'Cierre de ' + mesTexto + ': no quedó nada pendiente'
  : 'Cierre de ' + mesTexto + ': ' + filas.length +
    (filas.length === 1 ? ' pendiente' : ' pendientes');

const mensaje = todoAlDia
  ? '<div style="font-family:Inter,Arial,sans-serif;color:#333;max-width:720px;">' +
    '<h2 style="color:#30bbb7;margin:0 0 8px;">Cerraste ' + escapar(mesTexto) + ' limpio</h2>' +
    '<p style="margin:0;">No quedaron facturas sin cobrar, ni borradores sin emitir, ni compras sin pagar de ese mes.</p>' +
    '<p style="margin-top:24px;color:#888;font-size:12px;">Sale de tus documentos abiertos en Alegra.</p></div>'
  : '<div style="font-family:Inter,Arial,sans-serif;color:#333;max-width:720px;">' +
    '<h2 style="color:#30bbb7;margin:0 0 4px;">Lo que falta para cerrar ' + escapar(mesTexto) + '</h2>' +
    '<p style="margin:0 0 8px;color:#666;">' + filas.length +
    (filas.length === 1 ? ' pendiente' : ' pendientes') + ' en ' + tipos.length +
    (tipos.length === 1 ? ' frente' : ' frentes') + '. El detalle completo quedó en tu hoja de Google.</p>' +
    tipos.map(bloque).join('') +
    '<p style="margin-top:24px;color:#888;font-size:12px;">' +
    'Sale de tus documentos abiertos y en borrador en Alegra. Este flujo no cambia nada: solo te dice qué mirar.' +
    '</p></div>';

return [{ json: { asunto, mensaje, pendientes: todoAlDia ? 0 : filas.length, mesTexto } }];
